1	// andes-sim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace andes_sim {
20	int cmd_list(const Cli& cli);
21	int cmd_doctor(const Cli& cli);
22	int cmd_build(const Cli& cli);
23	int cmd_run(const Cli& cli);
24	int cmd_state_diff(const Cli& cli);
25	}  // namespace andes_sim
26	
27	namespace {
28	
29	using andes_sim::Cli;
30	using andes_sim::is_dev_mode;
31	
32	// Each command's release tier decides where it shows in `--help`:
33	//   Release -- the finished, user-facing product surface (always listed).
34	//   Dev     -- developer tooling, listed only when ANDES_SIM_DEV is set.
35	//   Hidden  -- a stable dispatch slot for an unfinished ROADMAP feature; never
36	//              listed (explicit invocation still hits the "not yet implemented"
37	//              stub), so the product never advertises half-built work.
38	enum class Tier { Release, Dev, Hidden };
39	
40	struct Subcommand {
41	  std::string_view name;
42	  std::string_view brief;
43	  Tier tier;
44	};
45	
46	// The full command surface. Names are fixed from F0 so usage, dispatch, and
47	// tests are stable; handlers arrive feature by feature. The tier (above) keeps
48	// dev and unfinished commands out of the release `--help` (see print_usage).
49	// Listed release-first, then dev, then hidden -- dispatch is by name, so the
50	// order is purely the display order.
51	constexpr Subcommand kSubcommands[] = {
52	    {"run", "run one simulation (--mode fast|cycle|hybrid)", Tier::Release},
53	    {"list", "list models|engines", Tier::Release},
54	    {"doctor", "check environment health", Tier::Release},
55	    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)",
56	     Tier::Dev},
57	    {"test", "run the end-to-end suite", Tier::Dev},
58	    {"state-diff", "compare two drained state files (oracle vs vsim)",
59	     Tier::Dev},
60	    {"profile", "profile a workload into a basic-block vector", Tier::Hidden},
61	    {"cluster", "cluster a BBV into SimPoint phases", Tier::Hidden},
62	    {"archive", "snapshot a drained state into a replayable dir", Tier::Hidden},
63	    {"replay", "replay a snapshot", Tier::Hidden},
64	    {"estimate",
65	     "whole-program cycle estimate (run --mode hybrid --trigger simpoint)",
66	     Tier::Hidden},
67	};
68	
69	const Subcommand* find(std::string_view name) {
70	  for (const Subcommand& s : kSubcommands)
71	    if (s.name == name) return &s;
72	  return nullptr;
73	}
74	
75	void print_command(std::FILE* out, const Subcommand& s) {
76	  std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
77	               s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
78	}
79	
80	void print_usage(std::FILE* out) {
81	  std::fputs("usage: andes-sim <cmd> [args...]\n\n", out);
82	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
83	             out);
84	  std::fputs("commands:\n", out);
85	  for (const Subcommand& s : kSubcommands)
86	    if (s.tier == Tier::Release) print_command(out, s);
87	
88	  if (is_dev_mode()) {
89	    std::fputs("\ndeveloper commands:\n", out);
90	    for (const Subcommand& s : kSubcommands)
91	      if (s.tier == Tier::Dev) print_command(out, s);
92	  } else {
93	    std::fputs("\n(set ANDES_SIM_DEV=1 to show developer commands)\n", out);
94	  }
95	}
96	
97	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
98	  std::fprintf(out, "usage: andes-sim %.*s [args...]\n\n",
99	               static_cast<int>(sc.name.size()), sc.name.data());
100	  std::fprintf(out, "%.*s\n", static_cast<int>(sc.brief.size()), sc.brief.data());
101	  if (sc.name == "run") {
102	    std::fputs(
103	        "\nselection:\n"
104	        "  --mode fast|cycle|hybrid          which composition to run\n"
105	        "  --engine <id>                      pick a specific engine "
106	        "(e.g. vsim:ax45mpv_premium)\n"
107	        "  --trigger marker|pc|icount            ROI delimiter (hybrid only)\n"
108	        "  --mem-size <spec>                  guest memory, e.g. 256M / 2G "
109	        "(max 2G; fast/hybrid)\n"
110	        "  --verify                           cross-check the run against a "
111	        "QEMU oracle (hybrid)\n",
112	        out);
113	    // Dev-only knobs, hidden from the release surface like the Dev commands.
114	    if (is_dev_mode())
115	      std::fputs(
116	          "  --cosim                            co-sim vs the QEMU oracle: "
117	          "hybrid (ROI checkpoints) or cycle (lock-step)\n"
118	          "  --cosim-interval <N>               hybrid: checkpoint every N "
119	          "retired insns (default 10000)\n"
120	          "  --cosim-refine                     hybrid: narrow the diverging "
121	          "window ~16x/pass toward the instruction\n"
122	          "  --cosim-max-records <K>            cycle lock-step: stop after K "
123	          "per-attempt records (0 = until exit)\n"
124	          "  --pc-start <sym|0x>                cycle lock-step: arm pc "
125	          "(default: the ELF entry)\n",
126	          out);
127	    std::fputs(
128	        "  -- <args...>                       forward everything after -- "
129	        "verbatim to the engine\n",
130	        out);
131	  } else if (sc.name == "list") {
132	    // fixtures lists internal test ELFs -- a developer target, shown only in
133	    // dev mode (the release product lists user-facing models + engines).
134	    std::fputs(is_dev_mode() ? "\ntargets: fixtures | models | engines\n"
135	                             : "\ntargets: models | engines\n",
136	               out);
137	  }
138	}
139	
140	}  // namespace
141	
142	int main(int argc, char** argv) {
143	  using namespace andes_sim;
144	
145	  Cli cli = parse_cli(argc, argv);
146	  if (!cli.error.empty()) {
147	    std::fprintf(stderr, "andes-sim: %s\n", cli.error.c_str());
148	    return 2;
149	  }
150	
151	  if (cli.subcommand.empty()) {  // no command, or top-level -h
152	    if (cli.help) {
153	      print_usage(stdout);
154	      return 0;
155	    }
156	    print_usage(stderr);
157	    return 2;
158	  }
159	
160	  const Subcommand* sc = find(cli.subcommand);
161	  if (!sc) {
162	    std::fprintf(stderr, "andes-sim: unknown command '%s'\n\n",
163	                 cli.subcommand.c_str());
164	    print_usage(stderr);
165	    return 2;
166	  }
167	
168	  if (cli.help) {
169	    print_subcommand_help(*sc, stdout);
170	    return 0;
171	  }
172	
173	  if (cli.subcommand == "list") return cmd_list(cli);
174	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
175	  if (cli.subcommand == "build") return cmd_build(cli);
176	  if (cli.subcommand == "run") return cmd_run(cli);
177	  if (cli.subcommand == "state-diff") return cmd_state_diff(cli);
178	
179	  // Remaining subcommands stub out until their feature lands. Resolve the repo
180	  // root so the discovery path stays live and observable.
181	  std::string root;
182	  try {
183	    root = repo_root().string();
184	  } catch (const std::exception& e) {
185	    root = std::string("<unknown: ") + e.what() + ">";
186	  }
187	  std::fprintf(stderr, "andes-sim %s: not yet implemented (repo root: %s)\n",
188	               cli.subcommand.c_str(), root.c_str());
189	  return 3;
190	}

